// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;
    function setUp() public {
        c = new DEP_BANK();
        c.SetMinSum(0);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();
    }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: amount}(abi.encodeWithSignature("Deposit()"));
        assertTrue(ok, "deposit to initialized contract with valid log must succeed");
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
